#include "burrow/crypto/md5.h"

#include "burrow/core.h"
#include "burrow/hash.h"
#include "burrow/mem.h"
#include "burrow/panic.h"
#include "burrow/slice.h"
#include "burrow/type.h"

#include <string.h>

typedef struct Md5Digest {
    uint32_t s[4];
    Byte x[MD5_BLOCK_SIZE];
    Int nx;
    uint64_t len;
} Md5Digest;

static inline uint32_t md5_rotl(uint32_t x, int k) {
    return (x << k) | (x >> (32 - k));
}

static inline uint32_t md5_le32(const Byte *p) {
    return (uint32_t)p[0] | (uint32_t)p[1] << 8 | (uint32_t)p[2] << 16 |
           (uint32_t)p[3] << 24;
}

/* Hashes n bytes of p, which is a whole number of blocks. */
static void md5_block(Md5Digest *dig, const Byte *p, Int n) {
    uint32_t a = dig->s[0], b = dig->s[1], c = dig->s[2], d = dig->s[3];
    for (Int i = 0; i <= n - MD5_BLOCK_SIZE; i += MD5_BLOCK_SIZE) {
        const Byte *q = p + i;
        uint32_t aa = a, bb = b, cc = c, dd = d;
        uint32_t x[16];
        for (Int j = 0; j < 16; j++)
            x[j] = md5_le32(q + 4 * j);

        a = b + md5_rotl((((c ^ d) & b) ^ d) + a + x[0] + 0xD76AA478U, 7);
        d = a + md5_rotl((((b ^ c) & a) ^ c) + d + x[1] + 0xE8C7B756U, 12);
        c = d + md5_rotl((((a ^ b) & d) ^ b) + c + x[2] + 0x242070DBU, 17);
        b = c + md5_rotl((((d ^ a) & c) ^ a) + b + x[3] + 0xC1BDCEEEU, 22);
        a = b + md5_rotl((((c ^ d) & b) ^ d) + a + x[4] + 0xF57C0FAFU, 7);
        d = a + md5_rotl((((b ^ c) & a) ^ c) + d + x[5] + 0x4787C62AU, 12);
        c = d + md5_rotl((((a ^ b) & d) ^ b) + c + x[6] + 0xA8304613U, 17);
        b = c + md5_rotl((((d ^ a) & c) ^ a) + b + x[7] + 0xFD469501U, 22);
        a = b + md5_rotl((((c ^ d) & b) ^ d) + a + x[8] + 0x698098D8U, 7);
        d = a + md5_rotl((((b ^ c) & a) ^ c) + d + x[9] + 0x8B44F7AFU, 12);
        c = d + md5_rotl((((a ^ b) & d) ^ b) + c + x[10] + 0xFFFF5BB1U, 17);
        b = c + md5_rotl((((d ^ a) & c) ^ a) + b + x[11] + 0x895CD7BEU, 22);
        a = b + md5_rotl((((c ^ d) & b) ^ d) + a + x[12] + 0x6B901122U, 7);
        d = a + md5_rotl((((b ^ c) & a) ^ c) + d + x[13] + 0xFD987193U, 12);
        c = d + md5_rotl((((a ^ b) & d) ^ b) + c + x[14] + 0xA679438EU, 17);
        b = c + md5_rotl((((d ^ a) & c) ^ a) + b + x[15] + 0x49B40821U, 22);
        a = b + md5_rotl((((b ^ c) & d) ^ c) + a + x[1] + 0xF61E2562U, 5);
        d = a + md5_rotl((((a ^ b) & c) ^ b) + d + x[6] + 0xC040B340U, 9);
        c = d + md5_rotl((((d ^ a) & b) ^ a) + c + x[11] + 0x265E5A51U, 14);
        b = c + md5_rotl((((c ^ d) & a) ^ d) + b + x[0] + 0xE9B6C7AAU, 20);
        a = b + md5_rotl((((b ^ c) & d) ^ c) + a + x[5] + 0xD62F105DU, 5);
        d = a + md5_rotl((((a ^ b) & c) ^ b) + d + x[10] + 0x02441453U, 9);
        c = d + md5_rotl((((d ^ a) & b) ^ a) + c + x[15] + 0xD8A1E681U, 14);
        b = c + md5_rotl((((c ^ d) & a) ^ d) + b + x[4] + 0xE7D3FBC8U, 20);
        a = b + md5_rotl((((b ^ c) & d) ^ c) + a + x[9] + 0x21E1CDE6U, 5);
        d = a + md5_rotl((((a ^ b) & c) ^ b) + d + x[14] + 0xC33707D6U, 9);
        c = d + md5_rotl((((d ^ a) & b) ^ a) + c + x[3] + 0xF4D50D87U, 14);
        b = c + md5_rotl((((c ^ d) & a) ^ d) + b + x[8] + 0x455A14EDU, 20);
        a = b + md5_rotl((((b ^ c) & d) ^ c) + a + x[13] + 0xA9E3E905U, 5);
        d = a + md5_rotl((((a ^ b) & c) ^ b) + d + x[2] + 0xFCEFA3F8U, 9);
        c = d + md5_rotl((((d ^ a) & b) ^ a) + c + x[7] + 0x676F02D9U, 14);
        b = c + md5_rotl((((c ^ d) & a) ^ d) + b + x[12] + 0x8D2A4C8AU, 20);
        a = b + md5_rotl((b ^ c ^ d) + a + x[5] + 0xFFFA3942U, 4);
        d = a + md5_rotl((a ^ b ^ c) + d + x[8] + 0x8771F681U, 11);
        c = d + md5_rotl((d ^ a ^ b) + c + x[11] + 0x6D9D6122U, 16);
        b = c + md5_rotl((c ^ d ^ a) + b + x[14] + 0xFDE5380CU, 23);
        a = b + md5_rotl((b ^ c ^ d) + a + x[1] + 0xA4BEEA44U, 4);
        d = a + md5_rotl((a ^ b ^ c) + d + x[4] + 0x4BDECFA9U, 11);
        c = d + md5_rotl((d ^ a ^ b) + c + x[7] + 0xF6BB4B60U, 16);
        b = c + md5_rotl((c ^ d ^ a) + b + x[10] + 0xBEBFBC70U, 23);
        a = b + md5_rotl((b ^ c ^ d) + a + x[13] + 0x289B7EC6U, 4);
        d = a + md5_rotl((a ^ b ^ c) + d + x[0] + 0xEAA127FAU, 11);
        c = d + md5_rotl((d ^ a ^ b) + c + x[3] + 0xD4EF3085U, 16);
        b = c + md5_rotl((c ^ d ^ a) + b + x[6] + 0x04881D05U, 23);
        a = b + md5_rotl((b ^ c ^ d) + a + x[9] + 0xD9D4D039U, 4);
        d = a + md5_rotl((a ^ b ^ c) + d + x[12] + 0xE6DB99E5U, 11);
        c = d + md5_rotl((d ^ a ^ b) + c + x[15] + 0x1FA27CF8U, 16);
        b = c + md5_rotl((c ^ d ^ a) + b + x[2] + 0xC4AC5665U, 23);
        a = b + md5_rotl((c ^ (b | ~d)) + a + x[0] + 0xF4292244U, 6);
        d = a + md5_rotl((b ^ (a | ~c)) + d + x[7] + 0x432AFF97U, 10);
        c = d + md5_rotl((a ^ (d | ~b)) + c + x[14] + 0xAB9423A7U, 15);
        b = c + md5_rotl((d ^ (c | ~a)) + b + x[5] + 0xFC93A039U, 21);
        a = b + md5_rotl((c ^ (b | ~d)) + a + x[12] + 0x655B59C3U, 6);
        d = a + md5_rotl((b ^ (a | ~c)) + d + x[3] + 0x8F0CCC92U, 10);
        c = d + md5_rotl((a ^ (d | ~b)) + c + x[10] + 0xFFEFF47DU, 15);
        b = c + md5_rotl((d ^ (c | ~a)) + b + x[1] + 0x85845DD1U, 21);
        a = b + md5_rotl((c ^ (b | ~d)) + a + x[8] + 0x6FA87E4FU, 6);
        d = a + md5_rotl((b ^ (a | ~c)) + d + x[15] + 0xFE2CE6E0U, 10);
        c = d + md5_rotl((a ^ (d | ~b)) + c + x[6] + 0xA3014314U, 15);
        b = c + md5_rotl((d ^ (c | ~a)) + b + x[13] + 0x4E0811A1U, 21);
        a = b + md5_rotl((c ^ (b | ~d)) + a + x[4] + 0xF7537E82U, 6);
        d = a + md5_rotl((b ^ (a | ~c)) + d + x[11] + 0xBD3AF235U, 10);
        c = d + md5_rotl((a ^ (d | ~b)) + c + x[2] + 0x2AD7D2BBU, 15);
        b = c + md5_rotl((d ^ (c | ~a)) + b + x[9] + 0xEB86D391U, 21);
        a += aa;
        b += bb;
        c += cc;
        d += dd;
    }
    dig->s[0] = a;
    dig->s[1] = b;
    dig->s[2] = c;
    dig->s[3] = d;
}

static void md5_reset(void *self) {
    Md5Digest *d = self;
    d->s[0] = 0x67452301U;
    d->s[1] = 0xEFCDAB89U;
    d->s[2] = 0x98BADCFEU;
    d->s[3] = 0x10325476U;
    d->nx = 0;
    d->len = 0;
}

static void md5_update(Md5Digest *d, const Byte *p, Int n) {
    d->len += (uint64_t)n;
    if (d->nx > 0) {
        Int k = MD5_BLOCK_SIZE - d->nx < n ? MD5_BLOCK_SIZE - d->nx : n;
        memcpy(d->x + d->nx, p, (size_t)k);
        d->nx += k;
        if (d->nx == MD5_BLOCK_SIZE) {
            md5_block(d, d->x, MD5_BLOCK_SIZE);
            d->nx = 0;
        }
        p += k;
        n -= k;
    }
    if (n >= MD5_BLOCK_SIZE) {
        Int k = n & ~(Int)(MD5_BLOCK_SIZE - 1);
        md5_block(d, p, k);
        p += k;
        n -= k;
    }
    if (n > 0) {
        memcpy(d->x, p, (size_t)n);
        d->nx = n;
    }
}

static void md5_check_sum(Md5Digest *d, Byte out[MD5_SIZE]) {
    /* Padding: add 1 bit and 0 bits until 56 bytes mod 64, then the length in
     * bits as a little endian 64 bit number. */
    Byte tmp[1 + 63 + 8] = {0x80};
    uint64_t pad = (55 - d->len) % 64;
    uint64_t bits = d->len << 3;
    for (int i = 0; i < 8; i++)
        tmp[1 + pad + (uint64_t)i] = (Byte)(bits >> (8 * i));
    md5_update(d, tmp, (Int)(1 + pad + 8));
    if (d->nx != 0)
        panic_str(BURROW_S("d.nx != 0"));
    for (Int i = 0; i < 4; i++) {
        out[4 * i] = (Byte)d->s[i];
        out[4 * i + 1] = (Byte)(d->s[i] >> 8);
        out[4 * i + 2] = (Byte)(d->s[i] >> 16);
        out[4 * i + 3] = (Byte)(d->s[i] >> 24);
    }
}

static Int md5_write(void *self, Slice p, Error *err) {
    md5_update(self, (const Byte *)p.p, p.len);
    BURROW_OUT(err, BURROW_NO_ERROR);
    return p.len;
}

static Slice md5_sum_append(void *self, Alloc *a, Slice in) {
    /* Work on a copy so the caller can keep writing. */
    Md5Digest d0 = *(Md5Digest *)self;
    Byte h[MD5_SIZE];
    md5_check_sum(&d0, h);
    if (in.elem == NULL)
        in = slice_nil(TYPE_BYTE);
    return slice_append(a, in, h, MD5_SIZE);
}

static Int md5_size(void *self) {
    (void)self;
    return MD5_SIZE;
}

static Int md5_block_size(void *self) {
    (void)self;
    return MD5_BLOCK_SIZE;
}

static const HashVT md5_vt = {
    {NULL, md5_write}, md5_sum_append, md5_reset, md5_size, md5_block_size,
};

Hash md5_new(Alloc *a) {
    Md5Digest *d = BURROW_NEW(a, Md5Digest);
    if (d == NULL)
        return (Hash){NULL, NULL};
    md5_reset(d);
    Hash h = {&md5_vt, d};
    return h;
}

Md5SumRet md5_sum(Slice data) {
    Md5Digest d;
    Md5SumRet r;
    md5_reset(&d);
    md5_update(&d, (const Byte *)data.p, data.len);
    md5_check_sum(&d, r.a);
    return r;
}
